import { expect, test, type Locator, type Page } from "@playwright/test";
import { existsSync } from "node:fs";
import path from "node:path";
import { launchPackagedApp, type LaunchedApp } from "./launch";

// Generated by `npm run fixtures`: 8 s and 45 s vertical clips.
const SHORT = path.resolve("fixtures", "vertical_1080x1920_30.mp4");
const LONG = path.resolve("fixtures", "long_45s.mp4");
const PRODUCT = "Levi's 501 Jeans";

let launched: LaunchedApp;
let page: Page;

test.beforeAll(async () => {
  test.skip(
    !existsSync(SHORT) || !existsSync(LONG),
    'Run "npm run fixtures" first.',
  );
  launched = await launchPackagedApp();
  page = await launched.app.firstWindow();
});

test.afterAll(async () => {
  await launched?.app.close();
});

const slot = (name: "before" | "after" | "broll") =>
  page.getByTestId(`slot-${name}`);
const win = () => page.getByTestId("trim-window");
const startHandle = () => page.getByTestId("trim-handle-start");
const endHandle = () => page.getByTestId("trim-handle-end");
const scrubber = () => page.getByTestId("scrubber");

type SavedClip = {
  trimStart: number;
  duration: number;
  sourceDuration: number;
};

// What autosave wrote to the database: the recipe of the open draft.
async function saved(index: number): Promise<SavedClip> {
  return page.evaluate(async (i) => {
    const id = await window.api.settings.getOpenDraft();
    const video = await window.api.videos.get(id as string);
    const recipe = JSON.parse((video as { recipeJson: string }).recipeJson);
    return recipe.clips[i];
  }, index);
}
const trimOf = async (index: number) => {
  const clip = await saved(index);
  return { start: clip.trimStart, duration: clip.duration };
};

async function box(locator: Locator) {
  const found = await locator.boundingBox();
  if (!found) {
    throw new Error("element has no box");
  }
  return found;
}

// A real pointer drag: many pointermove events, so the drag is computed from its origin.
async function drag(fromX: number, y: number, deltaX: number, steps = 12) {
  await page.mouse.move(fromX, y);
  await page.mouse.down();
  await page.mouse.move(fromX + deltaX, y, { steps });
  await page.mouse.up();
}

// Pixels per second of the clip, read off the window (its length is known).
async function pxPerSecond(lengthSeconds: number) {
  return (await box(win())).width / lengthSeconds;
}

test("trim: drag, edges, fields, keys, reset and a long clip", async () => {
  await test.step("set up a product and a draft with an 8 s and a 45 s clip", async () => {
    await page.getByRole("button", { name: "Choose another folder" }).click();
    await page.getByRole("button", { name: "Use this folder" }).click();
    await page.getByRole("button", { name: "Add your first product" }).click();
    const dialog = page.getByRole("dialog", { name: "Add product" });
    await dialog.getByLabel("Full name").fill(PRODUCT);
    await dialog.getByRole("button", { name: "Add product" }).click();
    await expect(dialog).toBeHidden();
    await page
      .getByRole("button", { name: "New Video", exact: true })
      .first()
      .click();
    await page.getByRole("option", { name: new RegExp(PRODUCT) }).click();
    await page.getByLabel("Before clip file").setInputFiles([SHORT]);
    await page.getByLabel("After clip file").setInputFiles([LONG]);
    for (const name of ["before", "after"] as const) {
      await expect(slot(name)).toHaveAttribute("data-status", "ready", {
        timeout: 90_000,
      });
    }
    await slot("before").getByRole("heading", { name: "Before" }).click();
    await expect(page.getByTestId("trim-section")).toBeVisible();
    await expect(page.getByTestId("trim-start")).toHaveValue("0.0");
    await expect(page.getByTestId("trim-duration")).toHaveValue("3.0");
  });

  await test.step("the filmstrip shows frames from the clip", async () => {
    const images = page.getByTestId("filmstrip").locator("img");
    await expect(images.first()).toBeVisible();
    await expect
      .poll(() =>
        images.first().evaluate((img) => {
          const image = img as HTMLImageElement;
          return image.complete && image.naturalWidth > 0;
        }),
      )
      .toBe(true);
  });

  await test.step("dragging the window body moves it and keeps its length", async () => {
    const pps = await pxPerSecond(3);
    const w = await box(win());
    await drag(w.x + w.width / 2, w.y + w.height / 2, 2 * pps);
    await expect.poll(() => trimOf(0)).toEqual({ start: 2, duration: 3 });
    await expect(page.getByTestId("trim-start")).toHaveValue("2.0");
  });

  await test.step("dragging the end handle changes the length", async () => {
    const pps = await pxPerSecond(3);
    const h = await box(endHandle());
    // The handle's visible bar is its first 4 px.
    await drag(h.x + 2, h.y + h.height / 2, pps);
    await expect.poll(() => trimOf(0)).toEqual({ start: 2, duration: 4 });
    // The Player shows the last frame of the clip while the right edge moves.
    await expect(scrubber()).toHaveValue("119");
  });

  await test.step("dragging the start handle keeps the end where it was", async () => {
    const pps = await pxPerSecond(4);
    const h = await box(startHandle());
    await drag(h.x + h.width - 2, h.y + h.height / 2, pps);
    await expect.poll(() => trimOf(0)).toEqual({ start: 3, duration: 3 });
    await expect(scrubber()).toHaveValue("0");
  });

  await test.step("Escape during a drag puts the window back and saves nothing", async () => {
    const pps = await pxPerSecond(3);
    const w = await box(win());
    const x = w.x + w.width / 2;
    const y = w.y + w.height / 2;
    await page.mouse.move(x, y);
    await page.mouse.down();
    await page.mouse.move(x - 2 * pps, y, { steps: 8 });
    await expect(page.getByTestId("trim-start")).toHaveValue("1.0");
    await page.keyboard.press("Escape");
    await page.mouse.up();
    await expect(page.getByTestId("trim-start")).toHaveValue("3.0");
    await expect.poll(() => trimOf(0)).toEqual({ start: 3, duration: 3 });
  });

  await test.step("the numeric fields clamp, snap and save at once", async () => {
    const start = page.getByTestId("trim-start");
    await start.fill("1.26");
    await start.press("Enter");
    await expect.poll(() => trimOf(0)).toEqual({ start: 1.3, duration: 3 });
    // Past the end of the 8 s clip: the window is pushed back inside.
    await start.fill("99");
    await start.press("Enter");
    await expect.poll(() => trimOf(0)).toEqual({ start: 5, duration: 3 });
    // A longer length than fits from here moves the start earlier.
    const length = page.getByTestId("trim-duration");
    await length.fill("6");
    await length.press("Enter");
    await expect.poll(() => trimOf(0)).toEqual({ start: 2, duration: 6 });
    // Nonsense goes back to the current value.
    await length.fill("abc");
    await length.press("Enter");
    await expect(length).toHaveValue("6.0");
    // Under the minimum rises to 0.5 s.
    await length.fill("0.1");
    await length.press("Enter");
    await expect.poll(() => trimOf(0)).toEqual({ start: 2, duration: 0.5 });
  });

  await test.step("Reset to default length keeps the start", async () => {
    await page.getByTestId("trim-reset").click();
    await expect.poll(() => trimOf(0)).toEqual({ start: 2, duration: 3 });
    await expect(page.getByTestId("trim-reset")).toBeDisabled();
  });

  await test.step("keys: arrows move the window, brackets move the edges", async () => {
    // A click focuses the window without moving it.
    const w = await box(win());
    await page.mouse.click(w.x + w.width / 2, w.y + w.height / 2);
    await expect(win()).toBeFocused();
    await page.keyboard.press("ArrowRight");
    await expect.poll(() => trimOf(0)).toEqual({ start: 2.1, duration: 3 });
    await page.keyboard.press("Shift+ArrowLeft");
    await expect.poll(() => trimOf(0)).toEqual({ start: 1.1, duration: 3 });
    await page.keyboard.press("BracketRight");
    await expect.poll(() => trimOf(0)).toEqual({ start: 1.1, duration: 3.1 });
    await page.keyboard.press("Shift+BracketRight");
    await expect.poll(() => trimOf(0)).toEqual({ start: 1.1, duration: 3 });
    await page.keyboard.press("BracketLeft");
    await expect.poll(() => trimOf(0)).toEqual({ start: 1, duration: 3.1 });
    await page.keyboard.press("Shift+BracketLeft");
    await expect.poll(() => trimOf(0)).toEqual({ start: 1.1, duration: 3 });
    // A focused handle: arrows move that edge only.
    await endHandle().focus();
    await page.keyboard.press("Shift+ArrowRight");
    await expect.poll(() => trimOf(0)).toEqual({ start: 1.1, duration: 4 });
  });

  await test.step("a held key is saved once it settles", async () => {
    await win().focus();
    for (let i = 0; i < 5; i++) {
      await page.keyboard.press("ArrowRight");
    }
    await expect.poll(() => trimOf(0)).toEqual({ start: 1.6, duration: 4 });
  });

  await test.step("a 3 s window on the 45 s clip can be dragged to the very end", async () => {
    await slot("after").getByRole("heading", { name: "After" }).click();
    const length = page.getByTestId("trim-duration");
    await length.fill("3");
    await length.press("Enter");
    await expect.poll(() => trimOf(1)).toEqual({ start: 0, duration: 3 });
    // About 20 px wide; drawn at least 24 px so it can still be grabbed.
    const w = await box(win());
    expect(w.width).toBeGreaterThanOrEqual(23);
    const track = await box(page.getByTestId("filmstrip").locator("> div"));
    await drag(w.x + w.width / 2, w.y + w.height / 2, track.width * 2, 20);
    const clip = await (async () => {
      await expect
        .poll(async () => (await saved(1)).trimStart)
        .toBeGreaterThan(40);
      return saved(1);
    })();
    expect(clip.sourceDuration).toBeGreaterThan(44.9);
    expect(clip.duration).toBe(3);
    expect(clip.trimStart + clip.duration).toBeCloseTo(clip.sourceDuration, 5);
    // The scrubber sits on the After clip's first frame: Before is 4 s, 120 frames.
    await expect(scrubber()).toHaveValue("120");
  });

  await test.step("the handles of a tiny window are still grabbable", async () => {
    const h = await box(startHandle());
    const before = (await saved(1)).trimStart;
    const pps =
      (await box(page.getByTestId("filmstrip").locator("> div"))).width / 45;
    // Grab 8 px left of the window (outside it) and pull the start earlier by 2 s.
    await drag(h.x + 4, h.y + h.height / 2, -2 * pps, 10);
    await expect
      .poll(async () => (await saved(1)).trimStart)
      .toBeLessThan(before - 1);
    const clip = await saved(1);
    expect(clip.trimStart + clip.duration).toBeCloseTo(clip.sourceDuration, 5);
  });
});
